import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Link, useNavigate } from 'react-router-dom';
import {
  ArrowUpRight,
  CalendarDays,
  ChevronRight,
  MapPinned,
  PackageX,
  ShoppingBag,
  TrendingUp,
  Truck,
  Users,
  Wallet,
} from 'lucide-react';
import { useAdmin } from '../lib/store';
import {
  AreaChart,
  Avatar,
  Donut,
  MapView,
  OrderStatusBadge,
  PageHeader,
  Progress,
  StatCard,
  cn,
} from '../lib/ui';
import { formatShort, formatUZS, monthlySeries, salesSeries } from '../lib/mock';

export const Dashboard = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const { orders, products, couriers, customers } = useAdmin();
  const [range, setRange] = useState<'today' | 'week' | 'month'>('week');

  const revenue = orders.filter((o) => o.status !== 'cancelled').reduce((s, o) => s + o.total, 0);
  const avgOrder = orders.length ? revenue / orders.length : 0;
  const lowStock = products.filter((p) => p.stock > 0 && p.stock <= 10);
  const outOfStock = products.filter((p) => p.stock === 0);
  const activeCouriers = couriers.filter((c) => c.status !== 'offline').length;
  const statusCounts = {
    new: orders.filter((o) => o.status === 'new').length,
    confirmed: orders.filter((o) => o.status === 'confirmed').length,
    preparing: orders.filter((o) => o.status === 'preparing').length,
    delivering: orders.filter((o) => o.status === 'delivering').length,
    delivered: orders.filter((o) => o.status === 'delivered').length,
    cancelled: orders.filter((o) => o.status === 'cancelled').length,
  };
  const donutTotal = Object.values(statusCounts).reduce((s, v) => s + v, 0);

  const topProducts = [...products].sort((a, b) => b.sold - a.sold).slice(0, 5);
  const recent = [...orders].slice(0, 5);
  const series = range === 'month' ? monthlySeries : salesSeries;

  return (
    <div className="animate-fade-up">
      <PageHeader
        title={t('welcome')}
        subtitle={t('dashboardSubtitle')}
        action={
          <div className="flex items-center gap-2">
            <div className="flex rounded-xl border p-1" style={{ borderColor: 'var(--border)', background: 'var(--surface)' }}>
              {(['today', 'week', 'month'] as const).map((r) => (
                <button
                  key={r}
                  onClick={() => setRange(r)}
                  className={cn(
                    'rounded-lg px-3 py-1.5 text-xs font-bold transition',
                    range === r ? 'bg-brand-600 text-white shadow-sm' : 'text-[var(--muted)] hover:text-[var(--text)]',
                  )}
                >
                  {t(r)}
                </button>
              ))}
            </div>
            <button className="btn-secondary btn-sm hidden sm:inline-flex">
              <CalendarDays size={14} /> 18 mart, 2025
            </button>
          </div>
        }
      />

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <StatCard
          label={t('revenue')}
          value={formatShort(revenue) + " so'm"}
          delta={{ value: '12.4% o\'tgan haftaga nisbatan', positive: true }}
          icon={<Wallet size={20} />}
          tone="brand"
        />
        <StatCard
          label={t('ordersCount')}
          value={String(orders.length)}
          delta={{ value: '8.2% o\'sish', positive: true }}
          icon={<ShoppingBag size={20} />}
          tone="sky"
        />
        <StatCard
          label={t('avgOrder')}
          value={formatShort(avgOrder) + " so'm"}
          delta={{ value: '3.1% pasayish', positive: false }}
          icon={<TrendingUp size={20} />}
          tone="violet"
        />
        <StatCard
          label={t('customersCount')}
          value={String(customers.length)}
          delta={{ value: '2 yangi bugun', positive: true }}
          icon={<Users size={20} />}
          tone="amber"
        />
      </div>

      <div className="mt-5 grid grid-cols-1 gap-5 xl:grid-cols-3">
        <div className="card p-5 xl:col-span-2">
          <div className="mb-4 flex flex-wrap items-start justify-between gap-3">
            <div>
              <h2 className="font-display text-lg font-extrabold">{t('salesAnalytics')}</h2>
              <p className="mt-0.5 text-xs text-[var(--muted)]">Yetkazilgan va faol buyurtmalar bo'yicha</p>
            </div>
            <div className="flex items-center gap-2">
              <span className="badge bg-brand-500/15 text-brand-700 dark:text-brand-300">
                <span className="h-1.5 w-1.5 rounded-full bg-brand-500" /> Jonli
              </span>
              <span className="rounded-lg border px-2.5 py-1 text-xs font-bold text-[var(--muted)]" style={{ borderColor: 'var(--border)' }}>
                {range === 'today' ? 'Bugun' : range === 'week' ? 'Bu hafta' : 'Bu yil'}
              </span>
            </div>
          </div>
          <AreaChart data={series} height={236} suffix={range === 'month' ? ' mln' : ' mln'} />
        </div>

        <div className="card p-5">
          <div className="mb-4 flex items-start justify-between">
            <div>
              <h2 className="font-display text-lg font-extrabold">{t('orderStatus')}</h2>
              <p className="mt-0.5 text-xs text-[var(--muted)]">Joriy holat taqsimoti</p>
            </div>
            <button className="icon-btn h-8 w-8" onClick={() => navigate('/orders')}>
              <ChevronRight size={16} />
            </button>
          </div>
          <Donut
            total={donutTotal}
            centerLabel="buyurtma"
            centerValue={String(donutTotal)}
            segments={[
              { label: t('new'), value: statusCounts.new, color: '#0ea5e9' },
              { label: t('confirmed'), value: statusCounts.confirmed, color: '#8b5cf6' },
              { label: t('preparing'), value: statusCounts.preparing, color: '#f59e0b' },
              { label: t('delivering'), value: statusCounts.delivering, color: '#3b82f6' },
              { label: t('delivered'), value: statusCounts.delivered, color: '#10b981' },
              { label: t('cancelled'), value: statusCounts.cancelled, color: '#f43f5e' },
            ]}
          />
          <div className="mt-5 grid grid-cols-2 gap-2">
            <div className="card-soft p-3">
              <p className="text-[10px] font-bold uppercase tracking-wider text-[var(--muted)]">Faol kuryer</p>
              <p className="mt-1 font-display text-lg font-extrabold">{activeCouriers}/{couriers.length}</p>
            </div>
            <div className="card-soft p-3">
              <p className="text-[10px] font-bold uppercase tracking-wider text-[var(--muted)]">O'rtacha yetkazish</p>
              <p className="mt-1 font-display text-lg font-extrabold">28 daq</p>
            </div>
          </div>
        </div>
      </div>

      <div className="mt-5 grid grid-cols-1 gap-5 xl:grid-cols-3">
        <div className="card p-5 xl:col-span-2">
          <div className="mb-4 flex items-center justify-between">
            <div>
              <h2 className="font-display text-lg font-extrabold">{t('recentOrders')}</h2>
              <p className="mt-0.5 text-xs text-[var(--muted)]">Oxirgi 5 ta buyurtma</p>
            </div>
            <Link to="/orders" className="flex items-center gap-1 text-xs font-bold text-brand-600 hover:gap-2 dark:text-brand-400">
              {t('viewAll')} <ArrowUpRight size={14} />
            </Link>
          </div>
          <div className="table-wrap -mx-2">
            <table className="data-table min-w-[560px]">
              <thead>
                <tr>
                  <th>#</th>
                  <th>{t('customer')}</th>
                  <th>{t('total')}</th>
                  <th>{t('status')}</th>
                  <th>{t('courier')}</th>
                </tr>
              </thead>
              <tbody>
                {recent.map((order) => {
                  const courier = couriers.find((c) => c.id === order.courierId);
                  return (
                    <tr key={order.id} className="cursor-pointer" onClick={() => navigate(`/orders?order=${order.id}`)}>
                      <td>
                        <span className="font-extrabold">#{order.id}</span>
                        <span className="mt-0.5 block text-[10px] text-[var(--muted)]">{order.createdAt.slice(11)}</span>
                      </td>
                      <td>
                        <div className="flex items-center gap-2.5">
                          <Avatar emoji={order.customer.slice(0, 1) === 'A' ? '👨' : '🧑'} size="sm" />
                          <div>
                            <p className="text-xs font-bold">{order.customer}</p>
                            <p className="text-[10px] text-[var(--muted)]">{order.items.length} ta mahsulot</p>
                          </div>
                        </div>
                      </td>
                      <td className="text-xs font-extrabold">{formatUZS(order.total)}</td>
                      <td><OrderStatusBadge status={order.status} /></td>
                      <td>
                        {courier ? (
                          <span className="flex items-center gap-1.5 text-xs font-semibold">
                            <span>{courier.emoji}</span> {courier.name.split(' ')[0]}
                          </span>
                        ) : (
                          <span className="badge bg-amber-500/15 text-amber-600 dark:text-amber-300">{t('unassigned')}</span>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>

        <div className="card p-5">
          <div className="mb-4 flex items-center justify-between">
            <div>
              <h2 className="font-display text-lg font-extrabold">{t('lowStockAlerts')}</h2>
              <p className="mt-0.5 text-xs text-[var(--muted)]">{lowStock.length + outOfStock.length} ta mahsulot e'tibor talab qiladi</p>
            </div>
            <Link to="/inventory" className="icon-btn h-8 w-8"><ChevronRight size={16} /></Link>
          </div>
          <div className="space-y-3">
            {[...outOfStock, ...lowStock].slice(0, 5).map((p) => (
              <div key={p.id} className="flex items-center gap-3 rounded-xl border p-2.5" style={{ borderColor: 'var(--border)' }}>
                <span className={cn('flex h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br text-lg', p.gradient)}>{p.emoji}</span>
                <div className="min-w-0 flex-1">
                  <p className="truncate text-xs font-bold">{p.name}</p>
                  <div className="mt-1 flex items-center gap-2">
                    <Progress value={(p.stock / 50) * 100} tone={p.stock === 0 ? 'rose' : 'amber'} />
                    <span className="shrink-0 text-[10px] font-bold text-[var(--muted)]">{p.stock} {p.unit}</span>
                  </div>
                </div>
                <PackageX size={15} className={p.stock === 0 ? 'text-rose-500' : 'text-amber-500'} />
              </div>
            ))}
          </div>
          <Link to="/inventory" className="btn-secondary mt-4 w-full">
            {t('inventory')} <ChevronRight size={14} />
          </Link>
        </div>
      </div>

      <div className="mt-5 grid grid-cols-1 gap-5 xl:grid-cols-3">
        <div className="card p-5">
          <div className="mb-4 flex items-center justify-between">
            <div>
              <h2 className="font-display text-lg font-extrabold">{t('topProducts')}</h2>
              <p className="mt-0.5 text-xs text-[var(--muted)]">Sotuv hajmi bo'yicha</p>
            </div>
            <Link to="/products" className="icon-btn h-8 w-8"><ChevronRight size={16} /></Link>
          </div>
          <div className="space-y-3.5">
            {topProducts.map((p, i) => (
              <div key={p.id} className="flex items-center gap-3">
                <span className="w-4 text-center text-xs font-extrabold text-[var(--muted)]">{i + 1}</span>
                <span className={cn('flex h-9 w-9 items-center justify-center rounded-xl bg-gradient-to-br text-base', p.gradient)}>{p.emoji}</span>
                <div className="min-w-0 flex-1">
                  <div className="flex items-center justify-between gap-2">
                    <p className="truncate text-xs font-bold">{p.name}</p>
                    <span className="text-[10px] font-bold text-[var(--muted)]">{p.sold} ta</span>
                  </div>
                  <div className="mt-1.5">
                    <Progress value={(p.sold / topProducts[0].sold) * 100} />
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="card p-5 xl:col-span-2">
          <div className="mb-4 flex flex-wrap items-center justify-between gap-2">
            <div>
              <h2 className="font-display text-lg font-extrabold">{t('liveCouriers')}</h2>
              <p className="mt-0.5 text-xs text-[var(--muted)]">Real vaqtda kuryerlar holati</p>
            </div>
            <div className="flex items-center gap-2">
              <span className="badge bg-brand-500/15 text-brand-700 dark:text-brand-300">
                <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-brand-500" /> {activeCouriers} onlayn
              </span>
              <Link to="/tracking" className="btn-secondary btn-sm">
                <MapPinned size={14} /> {t('tracking')}
              </Link>
            </div>
          </div>
          <MapView couriers={couriers} height={260} />
          <div className="mt-3 grid grid-cols-1 gap-2 sm:grid-cols-3">
            {couriers.filter((c) => c.status !== 'offline').slice(0, 3).map((c) => (
              <div key={c.id} className="flex items-center gap-2 rounded-xl border p-2" style={{ borderColor: 'var(--border)' }}>
                <Avatar emoji={c.emoji} size="sm" online />
                <div className="min-w-0 flex-1">
                  <p className="truncate text-[11px] font-bold">{c.name}</p>
                  <p className="text-[10px] text-[var(--muted)]">{c.activeOrders} faol buyurtma</p>
                </div>
                <Truck size={14} className="text-brand-500" />
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};
